package com.xnvalabs.smarteyex.data.glasses

import com.xnvalabs.smarteyex.data.glasses.GlassesVectors.hex
import org.junit.Assert.assertArrayEquals
import org.junit.Assert.assertEquals
import org.junit.Assert.assertFalse
import org.junit.Assert.assertNotNull
import org.junit.Assert.assertNull
import org.junit.Assert.assertTrue
import org.junit.Test

/**
 * Parity tests: the phone-side codec must agree byte-for-byte with the firmware. The vectors (GlassesVectors.kt) are
 * generated by tools/gen_protocol.py from independent references (Python hmac, zlib, audioop) and are the same ones the
 * firmware's host tests (firmware/test/host) check, so a mismatch on either side fails CI.
 */
class GlassesProtocolTest {
    @Test
    fun crc32MatchesReference() {
        for ((data, crc) in GlassesVectors.crc) assertEquals(crc, GlassesProtocol.crc32(hex(data)))
    }

    @Test
    fun hmacMatchesReference() {
        for ((key, msg, mac) in GlassesVectors.hmac) assertArrayEquals(hex(mac), GlassesProtocol.hmac(hex(key), hex(msg)))
    }

    @Test
    fun authTranscriptMatchesFirmware() {
        val secret = hex(GlassesVectors.AUTH_SECRET)
        val id = hex(GlassesVectors.AUTH_DEVICE_ID)
        val nc = hex(GlassesVectors.AUTH_NONCE_C)
        val ng = hex(GlassesVectors.AUTH_NONCE_G)
        assertArrayEquals(hex(GlassesVectors.AUTH_MAC_G), GlassesProtocol.glassesMac(secret, id, nc, ng))
        assertArrayEquals(hex(GlassesVectors.AUTH_MAC_C), GlassesProtocol.phoneMac(secret, id, ng, nc))
        val hello = GlassesProtocol.hello(nc, GlassesVectors.AUTH_MTU)
        assertEquals(19, hello.size)
        assertEquals(ProtocolIds.Auth.HELLO, hello[0].toInt())
        assertEquals(GlassesVectors.AUTH_MTU, (hello[17].toInt() and 0xFF) or ((hello[18].toInt() and 0xFF) shl 8))
        assertEquals(33, GlassesProtocol.proof(hex(GlassesVectors.AUTH_MAC_C)).size)
        assertEquals(33, GlassesProtocol.provision(secret).size)
    }

    @Test
    fun adpcmEncodeMatchesReference() {
        val st = AdpcmState(0, 0)
        val out = GlassesProtocol.adpcmEncode(st, GlassesVectors.adpcmPcm, 0, GlassesVectors.adpcmPcm.size)
        assertArrayEquals(hex(GlassesVectors.ADPCM_ENC), out)
        assertEquals(GlassesVectors.ADPCM_END_PRED, st.predictor)
        assertEquals(GlassesVectors.ADPCM_END_IDX, st.index)

        val st2 = AdpcmState(GlassesVectors.ADPCM_ENC2_PRED, GlassesVectors.ADPCM_ENC2_IDX)
        assertArrayEquals(hex(GlassesVectors.ADPCM_ENC2), GlassesProtocol.adpcmEncode(st2, GlassesVectors.adpcmPcm, 0, GlassesVectors.adpcmPcm.size))
        assertEquals(GlassesVectors.ADPCM_END2_PRED, st2.predictor)
        assertEquals(GlassesVectors.ADPCM_END2_IDX, st2.index)
    }

    @Test
    fun adpcmDecodeMatchesReference() {
        val st = AdpcmState(GlassesVectors.ADPCM_ENC2_PRED, GlassesVectors.ADPCM_ENC2_IDX)
        val pcm = GlassesProtocol.adpcmDecode(st, hex(GlassesVectors.ADPCM_ENC2))
        assertArrayEquals(GlassesVectors.adpcmDec2, pcm)
        assertEquals(GlassesVectors.ADPCM_END2_PRED, st.predictor)
        assertEquals(GlassesVectors.ADPCM_END2_IDX, st.index)
    }

    @Test
    fun audioFrameRoundTrip() {
        val before = AdpcmState(-1234, 40)
        val data = ByteArray(160) { it.toByte() }
        val frame = GlassesProtocol.buildAudioFrame(2, 65535, before, data)
        assertEquals(166, frame.size)
        val parsed = GlassesProtocol.parseAudioFrame(frame)
        assertNotNull(parsed)
        assertEquals(2, parsed!!.stream)
        assertEquals(65535, parsed.seq)
        assertEquals(-1234, parsed.state.predictor)
        assertEquals(40, parsed.state.index)
        assertArrayEquals(data, parsed.data)
        frame[5] = 89
        assertNull(GlassesProtocol.parseAudioFrame(frame))
    }

    @Test
    fun statusAndEventParsing() {
        val b = byteArrayOf(1, 87, 1, (ProtocolIds.Flag.AUTHENTICATED or ProtocolIds.Flag.PROVISIONED).toByte(), 0xAC.toByte(), 0x0F, 0x40, 0xE2.toByte(), 0x01, 0x00)
        val s = GlassesProtocol.parseStatus(b)
        assertNotNull(s)
        assertEquals(87, s!!.battery)
        assertEquals(4012, s.batteryMv)
        assertEquals(123456L, s.uptimeS)
        assertTrue(s.has(ProtocolIds.Flag.AUTHENTICATED))
        assertFalse(s.has(ProtocolIds.Flag.PAIRING_MODE))
        b[0] = 9
        assertNull(GlassesProtocol.parseStatus(b))

        val e = GlassesProtocol.parseEvent(byteArrayOf(ProtocolIds.Evt.CMD_ACK.toByte(), 3, 3, ProtocolIds.Cmd.PING.toByte(), 9, 0))
        assertNotNull(e)
        assertEquals(ProtocolIds.Evt.CMD_ACK, e!!.type)
        assertEquals(3, e.payload.size)
        assertNull(GlassesProtocol.parseEvent(byteArrayOf(1, 2, 5, 0)))

        val cmd = GlassesProtocol.command(ProtocolIds.Cmd.CAPTURE, 7, byteArrayOf(1, 20))
        assertArrayEquals(byteArrayOf(1, 7, 2, 1, 20), cmd)
    }

    @Test
    fun imageAssemblerReassemblesAndVerifiesCrc() {
        val img = ByteArray(1000) { (it * 7 + 3).toByte() }
        val crc = GlassesProtocol.crc32(img)
        val ready = CaptureReady(5, img.size, crc, 640, 480)
        val asm = ImageAssembler(ready)
        var off = 0
        var last = ImageAssembler.State.MORE
        while (off < img.size) {
            val n = minOf(239, img.size - off)
            val chunk = ByteArray(5 + n)
            chunk[0] = 5
            for (i in 0 until 4) chunk[1 + i] = (off shr (8 * i)).toByte()
            System.arraycopy(img, off, chunk, 5, n)
            last = asm.add(chunk)
            off += n
        }
        assertEquals(ImageAssembler.State.DONE, last)
        assertArrayEquals(img, asm.bytes())

        val bad = ImageAssembler(CaptureReady(6, 10, 123L, 1, 1))
        val gap = byteArrayOf(6, 4, 0, 0, 0, 1, 2, 3)  // chunk starts at offset 4 but nothing arrived before it
        assertEquals(ImageAssembler.State.BAD, bad.add(gap))
    }

    @Test
    fun captureReadyParsing() {
        val p = byteArrayOf(9, 0xE8.toByte(), 0x03, 0, 0, 0x78, 0x56, 0x34, 0x12, 0x80.toByte(), 0x02, 0xE0.toByte(), 0x01)
        val r = GlassesProtocol.parseCaptureReady(p)
        assertNotNull(r)
        assertEquals(1000, r!!.size)
        assertEquals(0x12345678L, r.crc)
        assertEquals(640, r.width)
        assertEquals(480, r.height)
        assertNull(GlassesProtocol.parseCaptureReady(ByteArray(12)))
    }

    @Test
    fun wavRoundTripAndResample() {
        val pcm = ShortArray(1600) { (8000 * Math.sin(it * 0.1)).toInt().toShort() }
        val wav = GlassesProtocol.pcmToWav(pcm)
        assertEquals(44 + pcm.size * 2, wav.size)
        assertArrayEquals(pcm, GlassesProtocol.wavToPcm16k(wav))
        val wav8k = GlassesProtocol.pcmToWav(ShortArray(800) { 1000 }, 8000)
        val up = GlassesProtocol.wavToPcm16k(wav8k)
        assertNotNull(up)
        assertEquals(1600, up!!.size)
        assertNull(GlassesProtocol.wavToPcm16k(ByteArray(10)))
    }
}
